18: <div class="shell">
19:   <header class="topbar"><div class="brand"><div class="brand-mark">✦</div> Velvet Hour</div><div class="top-note">A grown-up story · 18+</div></header>
20:   <main class="main"><section class="game" aria-live="polite">
21:     <div class="art" aria-label="Illustration of a rooftop lounge at night"><div class="moon"></div><div class="city"></div><div class="roof"></div><div class="plant"><i></i><i></i><i></i><i></i></div><div class="figure" id="figure"><div class="hair-back"></div><div class="hair"></div><div class="face"></div><div class="neck"></div><div class="body"></div><div class="earring"></div></div><div class="table"></div><div class="glass"></div><div class="glow"></div><div class="art-label"><small>Tonight's company</small><strong>Rowan, 29</strong></div></div>
22:     <div class="content" id="content"></div>
23:   </section></main>
24:   <footer class="footer"><span>Fictional adults · consent comes first</span><span>VELVET HOUR&nbsp; / &nbsp;01</span></footer>
25: </div><div class="toast" id="toast" role="status"></div>
26: <script>
27: const content=document.getElementById('content');
28: const figure=document.getElementById('figure');
29: const toastEl=document.getElementById('toast');
30: let state={turn:0,trust:2,chemistry:2,comfort:2};
31: const startMarkup=`<div class="eyebrow">A little after midnight</div><h1>Some nights<br>are made for<br>getting closer.</h1><p class="intro">A rooftop, a warm drink, and an intriguing stranger. Spend one evening with Rowan in this short, choice-driven story about chemistry, honesty, and the pleasure of taking things at your own pace.</p><label class="age-check"><input type="checkbox" id="adultCheck"><span>I’m 18 or older. I understand this is a fictional, non-explicit romance game.</span></label><div class="entry-actions"><button class="primary" id="begin" disabled>Enter the evening <span aria-hidden="true">↗</span></button><button class="text-button" id="about">What kind of game is this?</button></div><p class="fine" style="margin-top:18px">All characters are adults. No explicit sexual content. Every intimate moment is optional, mutual, and fade-to-black.</p>`;
32: const chapters=[
33:  {title:'The first spark',line:'“I’m glad you came. This place is usually my quiet little secret.” Rowan smiles, then gestures to the open seat. “What kind of evening were you hoping for?”',desc:'A breeze carries the scent of jasmine from the terrace planters. Rowan waits, genuinely curious.',prompt:'Set the tone',choices:[
34:   {label:'“Good conversation and no need to rush.”',sub:'Open, unhurried · builds trust',d:[2,1,2],note:'Rowan relaxes. “That sounds like exactly my speed.”'},
35:   {label:'“Surprise me. What do you love about this place?”',sub:'Curious and attentive · builds connection',d:[1,2,1],note:'Their eyes brighten as they tell you the story behind the rooftop.'},
36:   {label:'“I’d like to flirt a little, if you’re into that.”',sub:'Direct, with room for an honest answer',d:[1,2,1],note:'“I am,” Rowan says with a grin. “Thanks for asking.”'}]},
37:  {title:'A good question',line:'You find an easy rhythm. Rowan tells you they restore old photographs and collect stories from strangers on trains.',desc:'“I like the moments when people stop performing,” they say. “What makes you feel most like yourself?”',prompt:'Share a little',choices:[
38:   {label:'Talk about a small thing that brings you joy.',sub:'Personal and low-pressure · builds trust',d:[2,1,1],note:'Rowan listens closely, then shares a favorite small joy of their own.'},
39:   {label:'Ask what they hope to make more time for.',sub:'Thoughtful · deepens connection',d:[1,2,1],note:'Their answer turns into a story neither of you wants to interrupt.'},
40:   {label:'“I’m enjoying this. Want to sit a little closer?”',sub:'Check in before changing the mood',d:[1,2,2],note:'“Yes, I’d like that.” Rowan shifts closer, leaving plenty of room.'}]},
41:  {title:'The gentle pause',line:'A quiet song drifts across the rooftop. Rowan’s hand rests near yours on the table—not touching, just close.',desc:'The moment feels full of possibility. There’s no wrong way to meet it.',prompt:'Choose what feels right',choices:[
42:   {label:'Offer your hand, and let Rowan decide.',sub:'A clear invitation; their choice matters',d:[2,1,2],note:'Rowan meets your hand with theirs. The contact is warm, easy, and mutual.'},
43:   {label:'Keep talking; the conversation is the good part.',sub:'Connection doesn’t need to hurry',d:[2,1,2],note:'You both laugh. The unhurried moment becomes its own kind of closeness.'},
44:   {label:'Ask if they’d like to share a slow dance.',sub:'An invitation, never an expectation',d:[1,2,1],note:'“I’d love to.” Rowan stands, and you sway together beneath the city lights.'}]},
45:  {title:'One more moment',line:'The night has softened around you. Rowan looks at you with a warmth that feels earned, not assumed.',desc:'“I’ve had a lovely time,” they say. “Would you like to keep the evening going, or call it here on a high note?”',prompt:'Your night, your call',choices:[
46:   {label:'Suggest another date—somewhere in daylight.',sub:'Leave room for what comes next',d:[2,1,2],note:'“I’d really like that,” Rowan says, already smiling at the idea.'},
47:   {label:'Ask if they’d like to walk a little longer together.',sub:'A little more time, no pressure',d:[1,2,1],note:'Rowan nods. You step out into the cool night side by side.'},
48:   {label:'Thank them for the evening and say goodnight.',sub:'A lovely ending is a complete ending',d:[2,1,2],note:'“I’m glad we met,” Rowan says. You part with a genuine smile.'}]}
49: ];
50: function renderStart(){content.innerHTML=startMarkup;const check=document.getElementById('adultCheck'),begin=document.getElementById('begin');check.addEventListener('change',()=>begin.disabled=!check.checked);begin.addEventListener('click',()=>{if(check.checked){state={turn:0,trust:2,chemistry:2,comfort:2};renderScene()}});document.getElementById('about').addEventListener('click',()=>toast('A cozy, consent-first romance story. No explicit scenes.'));}
51: function renderMeters(){const values=[['Trust',state.trust,'trust'],['Spark',state.chemistry,'chemistry'],['Comfort',state.comfort,'']];return `<div class="meters">${values.map(([name,val,cls])=>`<div class="meter"><div class="meter-head"><span>${name}</span><b>${Math.min(5,val)}/5</b></div><div class="track"><div class="fill ${cls}" style="width:${Math.min(100,val*20)}%"></div></div></div>`).join('')}</div>`}
52: function renderScene(){const c=chapters[state.turn];figure.classList.toggle('smile',state.chemistry>=4);content.innerHTML=`<div class="scene-top"><span class="chapter">${c.title}</span><span class="turn">${state.turn+1} / ${chapters.length}</span></div>${renderMeters()}<p class="dialogue">${c.line}</p><p class="narration">${c.desc}</p><p class="prompt">${c.prompt}</p><div class="choices">${c.choices.map((choice,i)=>`<button class="choice" data-choice="${i}"><span class="num">0${i+1}</span><span>${choice.label}<small>${choice.sub}</small></span></button>`).join('')}</div><div class="statusline" id="statusline"></div>`;content.querySelectorAll('.choice').forEach(button=>button.addEventListener('click',()=>selectChoice(Number(button.dataset.choice))));}
53: function selectChoice(index){const c=chapters[state.turn],choice=c.choices[index];state.trust=Math.max(0,Math.min(5,state.trust+choice.d[0]));state.chemistry=Math.max(0,Math.min(5,state.chemistry+choice.d[1]));state.comfort=Math.max(0,Math.min(5,state.comfort+choice.d[2]));figure.classList.toggle('smile',state.chemistry>=4);const line=document.getElementById('statusline');line.textContent=choice.note;content.querySelectorAll('.choice').forEach(b=>b.disabled=true);setTimeout(()=>{state.turn++;state.turn<chapters.length?renderScene():renderEnding()},1050)}
54: function renderEnding(){let title,copy,extra;if(state.trust>=7&&state.comfort>=7&&state.chemistry>=7){title='A night to remember';copy='Under the soft glow of the city, you share a lingering, mutual kiss. When the evening ends, it ends gently—on your terms, with a promise to meet again. The rest of the story belongs to you.';extra='A rare kind of chemistry: warm, honest, and entirely your own.'}else if(state.trust>=7&&state.comfort>=6){title='Easy does it';copy='You trade numbers and make a plan for another evening. Nothing has to happen all at once; the promise of getting to know each other is more than enough for tonight.';extra='Trust made room for something lovely to grow.'}else if(state.chemistry>=6){title='A bright little spark';copy='You share a playful goodbye and leave the door open for another time. Whatever this becomes, you both got to choose it—one honest moment at a time.';extra='A spark is a beginning, not a promise.'}else{title='A lovely evening';copy='You say goodnight feeling lighter than when you arrived. Not every connection needs to turn into a romance; sometimes a kind conversation is the whole gift.';extra='You made the evening your own.'}figure.classList.toggle('smile',state.chemistry>=5);content.innerHTML=`<div class="eyebrow">The evening comes to a close</div><h2>${title}</h2><p class="intro">${copy}</p><p class="fine">${extra}</p>${renderMeters()}<div class="end-actions"><button class="primary" id="again">Play again <span aria-hidden="true">↻</span></button><button class="secondary" id="restart">Back to the beginning</button></div><p class="fine" style="margin-top:19px">Every ending is a good ending when it feels right to you.</p>`;document.getElementById('again').addEventListener('click',()=>{state={turn:0,trust:2,chemistry:2,comfort:2};renderScene()});document.getElementById('restart').addEventListener('click',renderStart)}
55: let toastTimer;function toast(text){toastEl.textContent=text;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2300)}
56: renderStart();
57: </script>
58: </body>
59: </html>

