const startMarkup=`<div class="eyebrow">Немного после полуночи</div><h1>Некоторые ночи<br>созданы для<br>сближения.</h1><p class="intro">Терраса на крыше, тёплый напиток и загадочный незнакомец. Проведите вечер с Роуэн в короткой романтической истории о симпатии, искренности и удовольствии не торопиться.</p><label class="age-check"><input type="checkbox" id="adultCheck"><span>Мне уже исполнилось 18 лет. Я понимаю, что это вымышленная романтическая игра без откровенных сцен.</span></label><div class="entry-actions"><button class="primary" id="begin" disabled>Начать вечер <span aria-hidden="true">↗</span></button><button class="text-button" id="about">Что это за игра?</button></div><p class="fine" style="margin-top:18px">Все персонажи — взрослые. Любая близость необязательна, взаимна и остаётся за кадром.</p>`;
const chapters=[
 {title:'The first spark',line:'“I’m glad you came. This place is usually my quiet little secret.” Rowan smiles, then gestures to the open seat. “What kind of evening were you hoping for?”',desc:'A breeze carries the scent of jasmine from the terrace planters. Rowan waits, genuinely curious.',prompt:'Set the tone',choices:[
  {label:'“Good conversation and no need to rush.”',sub:'Open, unhurried · builds trust',d:[2,1,2],note:'Rowan relaxes. “That sounds like exactly my speed.”'},
  {label:'“Surprise me. What do you love about this place?”',sub:'Curious and attentive · builds connection',d:[1,2,1],note:'Their eyes brighten as they tell you the story behind the rooftop.'},
  {label:'“I’d like to flirt a little, if you’re into that.”',sub:'Direct, with room for an honest answer',d:[1,2,1],note:'“I am,” Rowan says with a grin. “Thanks for asking.”'}]},
 {title:'A good question',line:'You find an easy rhythm. Rowan tells you they restore old photographs and collect stories from strangers on trains.',desc:'“I like the moments when people stop performing,” they say. “What makes you feel most like yourself?”',prompt:'Share a little',choices:[
  {label:'Talk about a small thing that brings you joy.',sub:'Personal and low-pressure · builds trust',d:[2,1,1],note:'Rowan listens closely, then shares a favorite small joy of their own.'},
  {label:'Ask what they hope to make more time for.',sub:'Thoughtful · deepens connection',d:[1,2,1],note:'Their answer turns into a story neither of you wants to interrupt.'},
  {label:'“I’m enjoying this. Want to sit a little closer?”',sub:'Check in before changing the mood',d:[1,2,2],note:'“Yes, I’d like that.” Rowan shifts closer, leaving plenty of room.'}]},
 {title:'The gentle pause',line:'A quiet song drifts across the rooftop. Rowan’s hand rests near yours on the table—not touching, just close.',desc:'The moment feels full of possibility. There’s no wrong way to meet it.',prompt:'Choose what feels right',choices:[
  {label:'Offer your hand, and let Rowan decide.',sub:'A clear invitation; their choice matters',d:[2,1,2],note:'Rowan meets your hand with theirs. The contact is warm, easy, and mutual.'},
  {label:'Keep talking; the conversation is the good part.',sub:'Connection doesn’t need to hurry',d:[2,1,2],note:'You both laugh. The unhurried moment becomes its own kind of closeness.'},
  {label:'Ask if they’d like to share a slow dance.',sub:'An invitation, never an expectation',d:[1,2,1],note:'“I’d love to.” Rowan stands, and you sway together beneath the city lights.'}]},
 {title:'One more moment',line:'The night has softened around you. Rowan looks at you with a warmth that feels earned, not assumed.',desc:'“I’ve had a lovely time,” they say. “Would you like to keep the evening going, or call it here on a high note?”',prompt:'Your night, your call',choices:[
  {label:'Suggest another date—somewhere in daylight.',sub:'Leave room for what comes next',d:[2,1,2],note:'“I’d really like that,” Rowan says, already smiling at the idea.'},
  {label:'Ask if they’d like to walk a little longer together.',sub:'A little more time, no pressure',d:[1,2,1],note:'Rowan nods. You step out into the cool night side by side.'},
  {label:'Thank them for the evening and say goodnight.',sub:'A lovely ending is a complete ending',d:[2,1,2],note:'“I’m glad we met,” Rowan says. You part with a genuine smile.'}]}
];
