python3 - <<'PY'
from pathlib import Path
html=Path('index.html').read_text()
probe='''<script>
window.addEventListener('load',()=>{
 const check=document.getElementById('adultCheck'); check.checked=true; check.dispatchEvent(new Event('change'));
 document.getElementById('begin').click();
 let rounds=0;
 function advance(){
  const art=document.querySelector('.scene-illustration svg');
  if(art) document.body.dataset.scene=(Number(document.body.dataset.scene||0)+1);
  const choice=document.querySelector('.choice');
  if(choice){choice.click();rounds++;setTimeout(advance,1100);}
  else if(document.querySelector('#again')) document.body.dataset.ending=document.querySelector('h2').textContent;
  else document.body.dataset.error='missing choices or ending';
 }
 setTimeout(advance,0);
});
</script>'''
html=html.replace('</body>',probe+'</body>')
Path('/tmp/opencode/game-test.html').write_text(html)
