chromium --headless --no-sandbox --disable-gpu --allow-file-access-from-files --virtual-time-budget=7000 --dump-dom file:///tmp/opencode/game-test.html 2>/tmp/opencode/chromium.log | grep -E 'data-(scene|ending|error)|scene-illustration|Uncaught' | tail -8
cat /tmp/opencode/chromium.log | grep -iE 'error|exception' | tail -10

