from itertools import product
choices=[[[2,1,2],[1,2,1],[1,2,1]],[[2,1,1],[1,2,1],[1,2,2]],[[2,1,2],[2,1,2],[1,2,1]],[[2,1,2],[1,2,1],[2,1,2]]]
outcomes={}
for route in product(range(3),repeat=4):
 stats=[2,2,2]
 for r,i in enumerate(route): stats=[min(5,s+d-1) for s,d in zip(stats,choices[r][i])]
 if stats[0]>=4 and stats[1]>=4 and stats[2]>=4: title='top'
 elif stats[0]>=4 and stats[2]>=4: title='slow'
 elif stats[1]>=4: title='spark'
 else: title='quiet'
 outcomes.setdefault(title,(route,stats))
print(outcomes)
