from pathlib import Path
import re
s=Path('index.html').read_text()
js=re.search(r'<script>(.*?)</script>',s,re.S).group(1)
Path('/tmp/opencode/game.js').write_text(js)
html=s.replace('</body>','''<script>
window.addEventListener('load',()=>{
 const route=[0,0,2,2];let round=0;
 const check=document.getElementById('adultCheck');check.checked=true;check.dispatchEvent(new Event('change'));document.getElementById('begin').click();
 function advance(){
  const art=document.querySelector('.scene-illustration svg');if(art)document.body.dataset.scene=(Number(document.body.dataset.scene||0)+1);
  const button=document.querySelectorAll('.choice')[route[round]];
  if(button){button.click();round++;setTimeout(advance,1100)}
  else if(document.querySelector('#again'))document.body.dataset.ending=document.querySelector('h2').textContent;
  else document.body.dataset.error='missing choices or ending';
 }
 setTimeout(advance,0);
});
</script></body>''')
Path('/tmp/opencode/game-test.html').write_text(html)
