node --check /tmp/opencode/game.js
chromium --headless --no-sandbox --disable-gpu --allow-file-access-from-files --virtual-time-budget=7000 --dump-dom file:///tmp/opencode/game-test.html 2>/dev/null | grep -o '<body[^>]*>' | tail -1

